mapper.select:
select * from Sys_Tool_Data_Backup mn

    
        and INSTR(mn.Stdb_Table_Code,#{params.stdbTableCode})
    
    
        and INSTR(mn.Stdb_Title,#{params.stdbTitle})
    
    
        and mn.Stdb_Time between #{params.timeStart} and #{params.timeEnd}
    


    
        order by mn.${params.sortFiled} ${params.sortType}
    
    
        order by ${params.sortSideFiled} ${params.sortType}
    
    
        order by mn.Stdb_Time desc

select count(*) from Sys_Tool_Data_Backup mn

    
        and INSTR(mn.Stdb_Table_Code,#{params.stdbTableCode})
    
    
        and INSTR(mn.Stdb_Title,#{params.stdbTitle})
    
    
        and mn.Stdb_Time between #{params.timeStart} and #{params.timeEnd}
    


    
        order by mn.${params.sortFiled} ${params.sortType}
    
    
        order by mn.Stdb_Time desc
